package br.com.luvi.financaspessoais.grupo.entity; import br.com.luvi.financaspessoais.usuario.entity.Usuario; import jakarta.persistence.*; import java.time.*; @Entity @Table(name="convites_grupo",uniqueConstraints=@UniqueConstraint(columnNames="token")) public class ConviteGrupo{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(optional=false)private Grupo grupo;@ManyToOne(optional=false)private Usuario criadoPor;@Column(nullable=false,length=80)private String token;@Column(nullable=false)private LocalDateTime expiraEm;@Column(nullable=false)private boolean usado=false;public Long getId(){return id;}public Grupo getGrupo(){return grupo;}public void setGrupo(Grupo v){grupo=v;}public Usuario getCriadoPor(){return criadoPor;}public void setCriadoPor(Usuario v){criadoPor=v;}public String getToken(){return token;}public void setToken(String v){token=v;}public LocalDateTime getExpiraEm(){return expiraEm;}public void setExpiraEm(LocalDateTime v){expiraEm=v;}public boolean isUsado(){return usado;}public void setUsado(boolean v){usado=v;}}